pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 a, uint256 b) internal {
        try c.SetMinSum(a) {} catch { return; }
        uint256 m1;
        try c.MinSum() returns (uint256 __r) { m1 = __r; } catch { return; }
        try c.SetMinSum(b) {} catch { return; }
        uint256 m2;
        try c.MinSum() returns (uint256 __r) { m2 = __r; } catch { return; }
        assertTrue(m1 == a && m2 == b);
    }

    function testFuzz_run(uint256 a, uint256 b) public {
        _run(a, b);
    }

    receive() external payable {}
}
